//! Deterministic `Kush.lock` generation and verification.
//!
//! Resolution is path-only, so the lock records the resolved package graph,
//! versions, entries, and direct dependency edges. It is compared byte for byte:
//! the writer is deterministic and `--locked` rejects any difference, including
//! a stale path or version.
use super::{Failure, Project};
use std::{
    fs,
    io::Write,
    path::{Component, Path, PathBuf},
};

pub const LOCK_NAME: &str = "Kush.lock";

pub fn expected_text(project: &Project) -> String {
    let mut out = String::from(
        "# This file is generated by kush. Do not edit it manually.\n\
         # It records the resolved local dependency graph.\n\nversion = 1\n",
    );
    for package in &project.dependencies {
        out.push_str("\n[[package]]\n");
        out.push_str(&format!("name = {}\n", toml_string(&package.name)));
        out.push_str(&format!("version = {}\n", toml_string(&package.version)));
        out.push_str(&format!(
            "path = {}\n",
            toml_string(&relative_path(&project.root, &package.root))
        ));
        out.push_str(&format!(
            "entry = {}\n",
            toml_string(&relative_path(
                &project.root,
                &package.root.join(&package.entry)
            ))
        ));
        let dependencies = package
            .dependencies
            .iter()
            .map(|dependency| toml_string(dependency))
            .collect::<Vec<_>>()
            .join(", ");
        out.push_str(&format!("dependencies = [{dependencies}]\n"));
    }
    out
}

pub fn verify_or_write(project: &Project, locked: bool) -> Result<PathBuf, Failure> {
    let path = project.root.join(LOCK_NAME);
    let expected = expected_text(project);
    let existing = match fs::read_to_string(&path) {
        Ok(text) => Some(text),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => None,
        Err(error) => {
            return Err(Failure::new(format!(
                "cannot read {}: {error}",
                path.display()
            )));
        }
    };
    if locked {
        match existing {
            None => {
                return Err(Failure::new(format!(
                    "{} is missing; run a project command without --locked to generate it",
                    path.display()
                )));
            }
            Some(existing) if existing != expected => {
                return Err(Failure::new(format!(
                    "{} is out of date; run a project command without --locked to update it",
                    path.display()
                )));
            }
            Some(_) => return Ok(path),
        }
    }
    if existing.as_deref() != Some(expected.as_str()) {
        write_lock(&path, &expected)?;
    }
    Ok(path)
}

/// Atomic and symlink-safe: an existing symbolic link at the lock path is
/// refused instead of being followed, and the replacement goes through a
/// per-process temporary file so a crash never leaves half a lock.
fn write_lock(path: &Path, text: &str) -> Result<(), Failure> {
    if let Ok(metadata) = fs::symlink_metadata(path)
        && metadata.file_type().is_symlink()
    {
        return Err(Failure::new(format!(
            "{} is not a regular file; remove it and run the command again",
            path.display()
        )));
    }
    static NEXT: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let name = path.file_name().map_or_else(
        || "Kush.lock".to_owned(),
        |name| name.to_string_lossy().into_owned(),
    );
    let temporary = path.with_file_name(format!(
        ".{name}.{}-{}.tmp",
        std::process::id(),
        NEXT.fetch_add(1, std::sync::atomic::Ordering::Relaxed)
    ));
    let result = (|| -> Result<(), Failure> {
        let mut file = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&temporary)
            .map_err(|e| Failure::new(format!("cannot write {}: {e}", path.display())))?;
        file.write_all(text.as_bytes())
            .map_err(|e| Failure::new(format!("cannot write {}: {e}", path.display())))?;
        drop(file);
        fs::rename(&temporary, path)
            .map_err(|e| Failure::new(format!("cannot replace {}: {e}", path.display())))
    })();
    if result.is_err() {
        let _ = fs::remove_file(&temporary);
    }
    result
}

fn relative_path(root: &Path, target: &Path) -> String {
    let root = components(root);
    let target = components(target);
    let common = root
        .iter()
        .zip(&target)
        .take_while(|(left, right)| left == right)
        .count();
    let mut parts = Vec::new();
    for _ in common..root.len() {
        parts.push("..".to_owned());
    }
    for component in &target[common..] {
        parts.push(component.clone());
    }
    if parts.is_empty() {
        ".".to_owned()
    } else {
        parts.join("/")
    }
}

fn components(path: &Path) -> Vec<String> {
    path.components()
        .filter_map(|component| match component {
            Component::Normal(part) => Some(part.to_string_lossy().into_owned()),
            Component::RootDir => Some(String::new()),
            _ => None,
        })
        .collect()
}

fn toml_string(text: &str) -> String {
    let mut out = String::with_capacity(text.len() + 2);
    out.push('"');
    for ch in text.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            ch if ch.is_control() => out.push_str(&format!("\\u{:04X}", ch as u32)),
            ch => out.push(ch),
        }
    }
    out.push('"');
    out
}
